const raw = $input.first().json;
const jobs = Array.isArray(raw) ? raw.slice(1) : [];
return jobs
  .filter(j => j && j.position)
  .map(j => ({
    json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || `https://remoteok.io/remote-jobs/${j.id}`,
      source: 'RemoteOK',
      location_text: j.location || 'Worldwide',
      salary: j.salary ? `$${j.salary_min || 0}-$${j.salary_max || 0}` : '',
      description: j.description || '',
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
      job_id: j.url || String(j.id)
    }
  }));

const raw = $input.first().json;
const jobs = raw?.jobs || [];
return jobs.map(j => ({
  json: {
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
    source: 'Remotive',
    location_text: j.candidate_required_location || 'Worldwide',
    salary: j.salary || '',
    description: j.description || '',
    posted_date: j.publication_date || '',
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.job_type || ''),
    job_id: j.url || ''
  }
}));

return $input.all().map(item => {
  const j = item.json;
  return {
    json: {
      job_title: j.title || '',
      company: (j.title || '').split(' at ').pop() || '',
      job_url: j.link || '',
      source: 'WeWorkRemotely',
      location_text: 'Worldwide',
      salary: '',
      description: j.content || j.contentSnippet || '',
      posted_date: j.pubDate || j.isoDate || '',
      tags: j.categories ? j.categories.join(', ') : '',
      job_id: j.link || ''
    }
  };
});

const raw = $input.first().json;
const jobs = raw?.jobs || raw?.data || (Array.isArray(raw) ? raw : []);
return jobs.map(j => ({
  json: {
    job_title: j.title || j.role || '',
    company: j.company?.name || j.companyName || '',
    job_url: j.url || j.applyUrl || `https://himalayas.app/jobs/${j.slug || j.id}`,
    source: 'Himalayas',
    location_text: j.location || 'Worldwide',
    salary: j.salary || (j.minSalary ? `$${j.minSalary}-$${j.maxSalary}` : ''),
    description: j.description || j.content || '',
    posted_date: j.publishedAt || j.createdAt || '',
    tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
    job_id: j.url || String(j.id || j.slug)
  }
}));

return $input.all().map(item => {
  const j = item.json;
  const title = j.title || '';
  const parts = title.split(' - ');
  return {
    json: {
      job_title: parts[0] || title,
      company: parts[1] || '',
      job_url: j.link || '',
      source: 'DynamiteJobs',
      location_text: 'Remote',
      salary: '',
      description: j.content || j.contentSnippet || j.summary || '',
      posted_date: j.pubDate || j.isoDate || '',
      tags: '',
      job_id: j.link || ''
    }
  };
});

const raw = $input.first().json;
const jobs = raw?.jobs || raw?.results || (Array.isArray(raw) ? raw : []);
return jobs.map(j => ({
  json: {
    job_title: j.title || j.role || '',
    company: j.company?.name || j.startup?.name || '',
    job_url: j.url || j.applyUrl || `https://www.workatastartup.com/jobs/${j.id}`,
    source: 'YCombinator',
    location_text: j.location || 'Remote',
    salary: j.salary || '',
    description: j.description || j.body || '',
    posted_date: j.createdAt || j.updated_at || '',
    tags: Array.isArray(j.skills) ? j.skills.join(', ') : '',
    job_id: j.url || String(j.id)
  }
}));

// Build lookup sets from existing Google Sheets data
const existingItems = $('Read Existing Job URLs').all();
const existingUrls = new Set();
const existingKeys = new Set();

for (const item of existingItems) {
  const row = item.json;
  if (row.job_url) existingUrls.add(String(row.job_url).trim());
  if (row.company && row.job_title) {
    existingKeys.add(`${String(row.company).toLowerCase().trim()}||${String(row.job_title).toLowerCase().trim()}`);
  }
}

const incoming = $('Merge 5 +YC').all();
const seenUrls = new Set(existingUrls);
const seenKeys = new Set(existingKeys);
const unique = [];

for (const item of incoming) {
  const job = item.json;
  const url = String(job.job_url || '').trim();
  const key = `${String(job.company || '').toLowerCase().trim()}||${String(job.job_title || '').toLowerCase().trim()}`;

  if (!url) continue;
  if (seenUrls.has(url)) continue;
  if (key !== '||' && seenKeys.has(key)) continue;

  seenUrls.add(url);
  seenKeys.add(key);
  unique.push(item);
}

return unique;

const rejectPatterns = [
  /\bus\s*only\b/i, /\bcanada\s*only\b/i, /\buk\s*only\b/i,
  /\beu\s*only\b/i, /\beurope\s*only\b/i, /\baustralia\s*only\b/i,
  /\bmust\s+be\s+based\s+in\b/i, /\bmust\s+live\s+in\b/i,
  /\bmust\s+be\s+authorized\s+to\s+work\s+in\b/i,
  /\bauthorized\s+to\s+work\s+in\s+the\s+(us|uk|eu|canada)/i,
  /\blocal\s+work\s+permit\s+required/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i,
  /\boffice\s+required\b/i,
  /\bremote\s+within\s+[a-z\s]{2,30}\s+only\b/i,
  /\bfixed\s+us\s+hours\b/i, /\bfixed\s+eu\s+hours\b/i,
  /\bno\s+international\s+applicants\b/i,
  /\brelocate\s+to\b/i,
  /\bmust\s+reside\s+in\b/i
];

const keepPatterns = [
  /worldwide\s+remote/i, /global\s+remote/i, /work\s+from\s+anywhere/i,
  /anywhere\s+in\s+the\s+world/i, /apac\s+remote/i,
  /international\s+contractors?\s+accepted/i,
  /contractor\s+role/i, /b2b\s+contractor/i,
  /hires\s+via\s+deel/i, /hires\s+via\s+remote\.com/i, /hires\s+via\s+oyster/i,
  /eor\s+supported/i, /employer\s+of\s+record/i,
  /remote.?first/i, /fully\s+distributed/i,
  /distributed\s+team/i, /open\s+to\s+contractors/i,
  /accepts\s+contractors/i
];

const passed = [];

for (const item of $input.all()) {
  const job = item.json;
  const searchText = [
    job.description || '',
    job.location_text || '',
    job.job_title || '',
    job.tags || ''
  ].join(' ');

  const hasKeepSignal = keepPatterns.some(p => p.test(searchText));
  if (hasKeepSignal) {
    passed.push({ json: { ...job, hard_filter: 'pass', hard_filter_reason: 'explicit_global_signal' } });
    continue;
  }

  const hasRejectSignal = rejectPatterns.some(p => p.test(searchText));
  if (hasRejectSignal) continue;

  passed.push({ json: { ...job, hard_filter: 'unclear', hard_filter_reason: 'no_explicit_restriction' } });
}

return passed;

const aiRaw = $input.item.json;
const job = $('Split In Batches').item.json;

// Parse AI response
let ai = {};
try {
  const content = aiRaw?.content?.[0]?.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) ai = JSON.parse(jsonMatch[0]);
} catch(e) {
  ai = { taiwan_eligible: 'unclear', reason: 'parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
}

// Hard reject
if (ai.decision === 'reject' || ai.taiwan_eligible === 'no') {
  return [{ json: { ...job, _rejected: true, reject_reason: ai.reason || 'AI: Taiwan ineligible', ai_response: ai } }];
}

const titleDesc = `${job.job_title || ''} ${job.description || ''} ${job.tags || ''}`;

// Async level detection
const asyncHighPatterns = [/\basync\b/i, /\basynchronous\b/i, /flexible\s+hours/i, /flexible\s+schedule/i, /own\s+your\s+schedule/i, /work\s+from\s+any\s+timezone/i];
const asyncMedPatterns = [/distributed\s+team/i, /remote.?first/i, /low\s+meeting/i, /work\s+across\s+time\s+zones/i];
const asyncRejectPatterns = [/strict\s+9.?to.?5/i, /fixed\s+(us|est|pst|cet)\s+hours/i, /daily\s+live\s+calls\s+required/i, /must\s+overlap\s+full\s+business\s+day/i];

const fullText = `${job.description || ''} ${job.location_text || ''}`;

if (asyncRejectPatterns.some(p => p.test(fullText))) {
  return [{ json: { ...job, _rejected: true, reject_reason: 'Fixed timezone hours conflict', ai_response: ai } }];
}

let asyncLevel = 'low';
if (asyncHighPatterns.some(p => p.test(fullText))) asyncLevel = 'high';
else if (asyncMedPatterns.some(p => p.test(fullText))) asyncLevel = 'medium';

// Role category
const highRolePatterns = [
  /data\s+analyst/i, /data\s+scientist/i, /business\s+intelligence/i,
  /\bBI\s+analyst\b/i, /marketing\s+analyst/i, /performance\s+marketing/i,
  /growth\s+analyst/i, /AI\s+marketing/i, /AI\s+automation/i,
  /AI\s+workflow/i, /creative\s+strategist/i, /martech/i,
  /machine\s+learning/i, /analytics\s+engineer/i, /marketing\s+automation/i
];
const adjRolePatterns = [
  /analyst/i, /\bdata\b/i, /marketing/i, /automation/i,
  /reporting/i, /insights/i, /operations\s+analyst/i
];

let roleCategory = 'other';
if (highRolePatterns.some(p => p.test(titleDesc))) roleCategory = 'primary';
else if (adjRolePatterns.some(p => p.test(titleDesc))) roleCategory = 'adjacent';

// Scoring
let score = 0;
const taiwanStatus = ai.taiwan_eligible || 'unclear';
const locationRisk = ai.location_risk || 'high';
const timezoneRisk = ai.timezone_risk || 'medium';

// Taiwan eligibility (40 pts)
if (taiwanStatus === 'yes') score += 40;
else if (locationRisk === 'low' || job.hard_filter === 'pass') score += 35;
else if (taiwanStatus === 'unclear' && locationRisk === 'medium') score += 20;
else if (taiwanStatus === 'unclear') score += 15;

// Async fit (25 pts)
if (asyncLevel === 'high') score += 25;
else if (asyncLevel === 'medium') score += 15;
else score += 5;

// Role fit (25 pts)
if (roleCategory === 'primary') score += 25;
else if (roleCategory === 'adjacent') score += 15;

// Salary (25 pts max)
const salaryText = String(job.salary || '');
const numMatches = salaryText.match(/\d+/g);
const maxSalary = numMatches ? Math.max(...numMatches.map(Number)) : 0;
if (maxSalary >= 5000) score += 25;
else if (maxSalary >= 3000) score += 15;
else if (salaryText.trim() !== '') score += 10;

// Why good fit
const whyParts = [];
if (taiwanStatus === 'yes') whyParts.push('Confirmed worldwide remote');
if (asyncLevel === 'high') whyParts.push('Clearly async workflow');
if (roleCategory === 'primary') whyParts.push('Strong role match for Jerry');
if (maxSalary >= 5000) whyParts.push('Salary above $5k/mo');
else if (maxSalary >= 3000) whyParts.push('Salary above $3k/mo');
if (ai.contractor_possible === 'yes') whyParts.push('Contractor/Deel friendly');

// Final decision
let finalDecision = 'manual_check';
if (taiwanStatus === 'yes' && score >= 85 && asyncLevel !== 'low' && locationRisk === 'low') {
  finalDecision = 'apply_immediately';
} else if (taiwanStatus === 'no' || locationRisk === 'high' || score < 70) {
  finalDecision = 'reject';
} else if (taiwanStatus === 'unclear' && score >= 85 && locationRisk === 'medium') {
  finalDecision = 'manual_check';
} else if (score >= 70) {
  finalDecision = 'keep';
}

return [{
  json: {
    ...job,
    ai_response: ai,
    taiwan_eligible: taiwanStatus,
    taiwan_reason: ai.reason || '',
    location_risk: locationRisk,
    timezone_risk: timezoneRisk,
    contractor_possible: ai.contractor_possible || 'unclear',
    async_level: asyncLevel,
    role_category: roleCategory,
    score,
    why_good_fit: whyParts.join('; '),
    final_decision: finalDecision,
    date_found: new Date().toISOString().split('T')[0],
    application_status: 'new',
    notes: ''
  }
}];

const coverLetterResp = $input.item.json;
const job = $('Score Gate 85').item.json;
const coverLetter = coverLetterResp?.content?.[0]?.text || '';
return [{ json: { ...job, cover_letter: coverLetter } }];

const all = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);

const topJobs = all
  .filter(j => !j._rejected && j.score >= 70)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10);

const manualCheck = all
  .filter(j => j.taiwan_eligible === 'unclear' && j.score >= 75)
  .slice(0, 5);

const rejectedSummary = {
  us_only: all.filter(j => j.reject_reason && /us only/i.test(j.reject_reason)).length,
  eu_only: all.filter(j => j.reject_reason && /eu only|europe only/i.test(j.reject_reason)).length,
  hybrid: all.filter(j => j.reject_reason && /hybrid/i.test(j.reject_reason)).length,
  timezone: all.filter(j => j.timezone_risk === 'high').length,
  total: all.filter(j => j._rejected || j.score < 70).length
};

const date = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

let msg = `Daily Taiwan Eligible Async Remote Jobs\n${date}\n\n`;
msg += `Found ${topJobs.length} eligible jobs today.\n\n`;

if (topJobs.length === 0) {
  msg += 'No jobs passed the Taiwan eligibility filter today.\n';
} else {
  msg += `TOP JOBS TODAY:\n${'='.repeat(40)}\n\n`;
  topJobs.forEach((job, i) => {
    msg += `${i + 1}. ${job.job_title}\n`;
    msg += `   Company: ${job.company}\n`;
    msg += `   Score: ${job.score}/100\n`;
    msg += `   Taiwan eligible: ${job.taiwan_eligible} (${job.taiwan_reason || 'see job'})\n`;
    msg += `   Async level: ${job.async_level}\n`;
    msg += `   Timezone risk: ${job.timezone_risk}\n`;
    msg += `   Salary: ${job.salary || 'Not listed'}\n`;
    msg += `   Why it fits Jerry: ${job.why_good_fit || 'See job description'}\n`;
    msg += `   Decision: ${job.final_decision}\n`;
    msg += `   Apply: ${job.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  msg += `\nMANUAL CHECK (unclear eligibility, high score):\n${'='.repeat(40)}\n`;
  manualCheck.forEach(job => {
    msg += `- ${job.job_title} @ ${job.company} | Score: ${job.score} | ${job.job_url}\n`;
  });
}

msg += `\nREJECTED SUMMARY:\n${'='.repeat(40)}\n`;
msg += `Total rejected today: ${rejectedSummary.total}\n`;
msg += `  US only: ${rejectedSummary.us_only}\n`;
msg += `  EU only: ${rejectedSummary.eu_only}\n`;
msg += `  Hybrid/onsite: ${rejectedSummary.hybrid}\n`;
msg += `  Timezone conflict: ${rejectedSummary.timezone}\n`;

return [{ json: { message: msg, topJobs, date } }];

